/**
 * TinyMCE Math Plugin
 * A simple math plugin using KaTeX for equation rendering
 */
tinymce.PluginManager.add('math', function(editor, url) {
    var openDialog = function() {
        var win = editor.windowManager.open({
            title: 'Insert Math Equation',
            body: {
                type: 'panel',
                items: [
                    {
                        type: 'textarea',
                        name: 'latex',
                        label: 'LaTeX Code',
                        placeholder: 'Enter LaTeX equation here (e.g., x = \\frac{-b \\pm \\sqrt{b^2-4ac}}{2a})'
                    },
                    {
                        type: 'htmlpanel',
                        html: '<div id="math-preview" style="padding: 10px; border: 1px solid #ccc; margin: 10px 0; min-height: 50px; background: white;"></div>'
                    }
                ]
            },
            buttons: [
                {
                    type: 'cancel',
                    text: 'Close'
                },
                {
                    type: 'submit',
                    text: 'Insert',
                    primary: true
                }
            ],
            onSubmit: function(api) {
                var data = api.getData();
                if (data.latex) {
                    var html = '<span class="math-equation" data-latex="' + tinymce.DOM.encode(data.latex) + '">' + tinymce.DOM.encode(data.latex) + '</span>';
                    editor.insertContent(html);
                    api.close();
                }
            },
            initialData: {
                latex: ''
            }
        });

        // Add KaTeX script and preview functionality
        var katexScript = document.createElement('script');
        katexScript.src = 'https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/katex.min.js';
        katexScript.onload = function() {
            var katexCss = document.createElement('link');
            katexCss.rel = 'stylesheet';
            katexCss.href = 'https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/katex.min.css';
            document.head.appendChild(katexCss);

            // Add preview functionality
            var previewEl = win.getEl().querySelector('#math-preview');
            var textarea = win.getEl().querySelector('textarea');
            
            if (textarea && previewEl) {
                var updatePreview = function() {
                    try {
                        katex.render(textarea.value, previewEl, {
                            throwOnError: false,
                            displayMode: false
                        });
                    } catch (e) {
                        previewEl.innerHTML = '<span style="color: red;">Invalid LaTeX syntax</span>';
                    }
                };
                
                textarea.addEventListener('input', updatePreview);
                updatePreview();
            }
        };
        document.head.appendChild(katexScript);
    };

    editor.ui.registry.addButton('math', {
        tooltip: 'Insert Math Equation',
        icon: 'formula',
        onAction: function() {
            openDialog();
        }
    });

    editor.ui.registry.addMenuItem('math', {
        text: 'Math Equation',
        icon: 'formula',
        onAction: function() {
            openDialog();
        }
    });

    // Convert math equations to rendered HTML on content init
    editor.on('init', function() {
        var katexScript = document.createElement('script');
        katexScript.src = 'https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/katex.min.js';
        katexScript.onload = function() {
            var katexCss = document.createElement('link');
            katexCss.rel = 'stylesheet';
            katexCss.href = 'https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/katex.min.css';
            document.head.appendChild(katexCss);

            // Render existing math equations
            var mathElements = editor.getDoc().querySelectorAll('.math-equation');
            mathElements.forEach(function(el) {
                var latex = el.getAttribute('data-latex');
                if (latex) {
                    try {
                        katex.render(latex, el, {
                            throwOnError: false,
                            displayMode: false
                        });
                    } catch (e) {
                        el.textContent = latex;
                    }
                }
            });
        };
        document.head.appendChild(katexScript);
    });

    return {
        getMetadata: function() {
            return {
                name: 'Math Plugin',
                url: 'https://github.com/tinymce/tinymce'
            };
        }
    };
});
